dtsPropsFor.AgentTrace:
/** Ordered, human-readable reasoning steps. Rendered as a numbered list. */
  steps: string[];
  /** Model confidence in the 0-1 range. Rendered as a percentage badge when present. */
  confidence?: number;

dtsPropsFor.GraphViewer:
/** Cytoscape elements. Each node and edge wraps its fields in a `data` object. */
  elements: {
    nodes: { data: { id: string; label: string; type: string; court?: string | null } }[];
    edges: { data: { id: string; source: string; target: string; type: string } }[];
  };
  /** Canvas height in px. Defaults to 600. */
  height?: number;

dtsPropsFor.QuestionCard:
/** The LSAT item to render, including its answer choices and explanation. */
  question: {
    id: string;
    section: 'LR' | 'RC' | 'LG';
    type: string;
    difficulty: string;
    stem: string;
    choices: { label: string; text: string }[];
    /** Label of the correct choice, e.g. 'C'. */
    correct: string;
    explanation: string;
    source?: string | null;
    concepts?: string[];
    references?: { title: string; url: string; note?: string | null }[];
    passage_id?: string | null;
  };
  /** 0-based position of this question within the drill. */
  index: number;
  /** Total questions in the drill, shown as 'Question index+1 of total'. */
  total: number;
  /** Called with screen-reader announcements as the user answers. */
  onAnnounce?: (msg: string) => void;

dtsPropsFor.PassagePanel:
/** Reading-comprehension passage or logic-games setup shown beside the questions. */
  passage: {
    id: string;
    section: 'LR' | 'RC' | 'LG';
    title: string;
    summary?: string;
    passage?: string;
    setup?: string;
    rules?: string[];
    source?: string | null;
  };

dtsPropsFor.Drill:
/** Which LSAT section to drill. */
  section: 'LR' | 'RC' | 'LG';
  /** Called with screen-reader announcements as the user moves through questions. */
  onAnnounce?: (msg: string) => void;
